<?php require_once 'includes/db.php'; $pageTitle='Transportadores'; require 'includes/header.php'; $rows=$pdo->query('SELECT * FROM transportadores ORDER BY id DESC')->fetchAll(); ?><div class="page-heading"><div><h1 class="h3 mb-1">Transportadores</h1><p class="text-secondary mb-0">Cadastre motoristas ou empresas responsáveis pelo transporte.</p></div><a class="btn btn-primary" href="transportador_form.php">+ Cadastrar transportador</a></div><div class="card p-3"><div class="table-responsive"><table class="table"><thead><tr><th>Nome</th><th>Documento</th><th>Telefone</th><th>Veículo / placa</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['nome'])?></td><td><?=e($r['documento'])?></td><td><?=e($r['telefone'])?></td><td><?=e($r['veiculo'].' / '.$r['placa'])?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="transportador_form.php?id=<?=$r['id']?>">Editar</a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('Excluir transportador?')" href="delete.php?tipo=transportador&id=<?=$r['id']?>">Excluir</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5" class="text-center text-secondary">Nenhum transportador cadastrado.</td></tr><?php endif; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
